//! Mega Scale Native Type Kernel Engine (mega_kernel_a.rs) for Issue #142.

use pyo3::prelude::*;
use std::collections::HashMap;

pub struct MegaKernelA {
    pub key: String,
    pub data: HashMap<String, String>,
}

impl MegaKernelA {
    pub fn new(key: &str) -> Self {
        Self {
            key: key.to_string(),
            data: HashMap::new(),
        }
    }
}

/// Native Type Engine Rule #1
pub fn execute_mega_type_rule_1(engine: &mut MegaKernelA, k: &str, v: &str) -> bool {
    if k.is_empty() {
        return false;
    }
    engine.data.insert(k.to_string(), v.to_string());
    true
}

